package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Instant;import java.util.Objects;import java.util.Optional;
public record RecoveryCode(String recoveryCodeId,CredentialSubjectType subjectType,String subjectId,String codeHash,Instant createdAt,Optional<Instant> usedAt){public RecoveryCode{recoveryCodeId=Text.required(recoveryCodeId,"recoveryCodeId",128);Objects.requireNonNull(subjectType,"subjectType");subjectId=Text.required(subjectId,"subjectId",128);codeHash=Text.required(codeHash,"codeHash",512);Objects.requireNonNull(createdAt,"createdAt");usedAt=usedAt==null?Optional.empty():usedAt;}public boolean used(){return usedAt.isPresent();}public RecoveryCode markUsed(Instant at){if(used())throw new AuthenticationDomainException(AuthenticationReasonCode.AUTH_RECOVERY_CODE_USED,"Recovery code was already used");return new RecoveryCode(recoveryCodeId,subjectType,subjectId,codeHash,createdAt,Optional.of(at));}}
